contract:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout",
    "input_channel": "stdin",
    "output_channel": "stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= len(t) <= 10000",
      "description": "The length of the ciphered text t is between 1 and 10,000 inclusive."
    },
    {
      "id": "P2",
      "expression": "t.islower() and t.isalpha()",
      "description": "The ciphered text t consists of lowercase English letters only."
    },
    {
      "id": "P3",
      "expression": "1 <= m <= 100000",
      "description": "The number of words m is between 1 and 100,000 inclusive."
    },
    {
      "id": "P4",
      "expression": "all(1 <= len(wi) <= 1000 for wi in words)",
      "description": "Each word wi in the list of words has a length between 1 and 1000 inclusive."
    },
    {
      "id": "P5",
      "expression": "all(wi.isalpha() for wi in words)",
      "description": "Each word wi in the list of words consists of English letters only."
    },
    {
      "id": "P6",
      "expression": "sum(len(wi) for wi in words) <= 1000000",
      "description": "The total length of all words in the list does not exceed 1,000,000."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "all(wi.lower()[::-1] in t for wi in sentence.split())",
      "description": "Each word in the original sentence, when reversed and converted to lowercase, is a substring of the ciphered text t."
    },
    {
      "id": "Q2",
      "expression": "".join(wi.lower()[::-1] for wi in sentence.split()) == t",
      "description": "The concatenation of the reversed and lowercase versions of the words in the original sentence matches the ciphered text t."
    },
    {
      "id": "Q3",
      "expression": "all(wi in words for wi in sentence.split())",
      "description": "Each word in the original sentence is one of the given words."
    }
  ],
  "invariants": []
}
